<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class DokumenPublikasi extends Model {protected $table='dokumen_publikasi'; protected $fillable=['tahun_anggaran_id','kategori','judul','deskripsi','file_path','status_publikasi','tanggal_publikasi']; protected $casts=['tanggal_publikasi'=>'date']; public function tahunAnggaran(){return $this->belongsTo(TahunAnggaran::class);} public function scopePublik($q){return $q->where('status_publikasi','dipublikasikan');}}
